draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // book
  ctx.fillStyle = '#663300';
  ctx.fillRect(W/2-50, H/2-50, 100, 100);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.strokeRect(W/2-50, H/2-50, 100, 100);

  // stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2+70, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+50);
  ctx.lineTo(W/2, H/2+90);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+70);
  ctx.lineTo(W/2-30, H/2+90);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+70);
  ctx.lineTo(W/2+30, H/2+90);
  ctx.stroke();

  // applying lesson
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Apply', W/2, H/2-120+50*Math.sin(t));

  // life
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Life', W/2, H/2-80+50*Math.cos(t));

  // 504
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('504', W/2, H/2-40+50*Math.sin(t+Math.PI/2));

  ctx.restore();
}
